style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://www.tusitio.com/dmc.jpg"); /* reemplaza esta URL con la verdadera */
        background-size: cover;
        background-repeat: no-repeat;
        background-attachment: fixed;
        background-position: center center;
    }

    /* Opcional: hacer los contenidos principales un poco transparentes */
    .container-main, .content, .container-footer {
        background-color: rgba(255, 255, 255, 0.85) !important;
    }
}
